def sha3_512_hex(data: bytes) -> str:
    return hashlib.sha3_512(data).hexdigest()


def det_wallet(chain: str, index: int) -> str:
    return f"0x{det_hex(chain, index, 'wallet')[:40]}"


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_iso_date(value: Any) -> Optional[datetime]:
    """Parse YYYY-MM-DD or ISO-8601 timestamps for temporal integrity checks."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    text = str(value).strip()
    if not text:
        return None
    try:
        if text.isdigit() and len(text) >= 10:
            return datetime.fromtimestamp(int(text[:10]), tz=timezone.utc)
        if len(text) == 10 and text[4] == "-" and text[7] == "-":
            return datetime.strptime(text, "%Y-%m-%d").replace(tzinfo=timezone.utc)
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except (ValueError, TypeError, OSError):
        return None


def extract_uspto_patent_dates(item: Dict[str, Any]) -> Tuple[str, str, Dict[str, Any]]:
    """
    Extract filing vs grant dates from USPTO payloads without illegal conflation.
    USPTO bulk `patent_date` is treated as grant/issue date only.
    """
    meta: Dict[str, Any] = {"source": "uspto_primary_fields"}
    filing = (
        item.get("appFilingDate")
        or item.get("applicationFilingDate")
        or item.get("filingDate")
        or item.get("filing_date")
        or item.get("app_filing_date")
        or ""
    )
    grant = (
        item.get("patent_date")
        or item.get("grantDate")
        or item.get("issueDate")
        or item.get("publicationDate")
        or item.get("grant_date")
        or ""
    )
    filing = str(filing).strip()
    grant = str(grant).strip()
    if filing and grant and filing == grant:
        meta["conflation_detected"] = True
        meta["manipulation_class"] = "CONFLATED_FILING_GRANT"
        if item.get("patent_date") and not item.get("filingDate"):
            filing = ""
            meta["filing_cleared"] = "patent_date_grant_only"
    if not filing and not grant:
        meta["missing_primary_dates"] = True
    return filing, grant, meta


def tx_timestamp_float(
    tx: Any,
    *,
    fallback_hash: Optional[str] = None,
) -> float:
    """Normalize blockchain tx timestamps to Unix seconds (float)."""
    raw = getattr(tx, "timestamp", None)
    if raw is None:
        block = getattr(tx, "block_number", None)
        if block is not None:
            return float(block)
        tx_hash = fallback_hash or getattr(tx, "tx_hash", "")
        return float(det_hash(tx_hash) % 1_000_000)

    if isinstance(raw, datetime):
        if raw.tzinfo is None:
            raw = raw.replace(tzinfo=timezone.utc)
        return float(raw.timestamp())

    if isinstance(raw, (int, float)):
        return float(raw)

    if isinstance(raw, str):
        try:
            return float(raw)
        except ValueError:
            try:
                parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                return float(parsed.timestamp())
            except ValueError:
                pass

    tx_hash = fallback_hash or getattr(tx, "tx_hash", "")
    return float(det_hash(tx_hash) % 1_000_000)


