        ("0001744489", "Walt Disney Co", ("S&P_500", "FORTUNE_500", "GLOBAL_2000", "FORTUNE_5000")),
        ("0001065280", "Netflix Inc", ("S&P_500", "FORTUNE_500", "GLOBAL_2000", "FORTUNE_5000")),
