class VLLMInferenceOrchestrator:
    """Maximize vLLM throughput for forensic narrative synthesis and flow analysis."""

    @classmethod
    async def infer(
        cls,
        session: ClientSession,
        prompt: str,
        *,
        max_tokens: int = 4096,
        temperature: float = 0.1,
    ) -> Dict[str, Any]:
        payload = {
            "model": VLLM_MODEL,
            "messages": [
                {
                    "role": "system",
                    "content": (
                        "You are a federal forensic analyst documenting illicit blockchain "
                        "transaction flows for DOJ prosecutorial referral. Be precise, "
                        "chronological, and cite statutes where applicable."
                    ),
                },
                {"role": "user", "content": prompt},
            ],
            "max_tokens": max_tokens,
            "temperature": temperature,
        }
        url = f"{VLLM_ENDPOINT.rstrip('/')}/chat/completions"
        try:
            async with session.post(url, json=payload, timeout=ClientTimeout(total=120)) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    content = (
                        data.get("choices", [{}])[0]
                        .get("message", {})
                        .get("content", "")
                    )
                    return {
                        "success": True,
                        "content": content,
                        "backend": "vllm",
                        "model": VLLM_MODEL,
                        "endpoint": VLLM_ENDPOINT,
                        "tokens_used": data.get("usage", {}),
                    }
        except (aiohttp.ClientError, asyncio.TimeoutError) as exc:
            logger.info("vLLM endpoint unavailable (%s); using deterministic synthesis", exc)
        return {
            "success": False,
            "content": "",
            "backend": "deterministic_fallback",
            "model": VLLM_MODEL,
            "endpoint": VLLM_ENDPOINT,
        }


