def _foley_name_variants(name: str) -> List[str]:
    variants = {name.strip(), re.sub(r"\s+", " ", name).strip(), name.replace(".", "").strip()}
    parts = name.split()
    if len(parts) >= 2:
        variants.add(f"{parts[0]} {parts[-1]}")
        if len(parts) >= 3 and len(parts[1].rstrip(".")) <= 2:
            variants.add(f"{parts[0]} {parts[1]} {parts[-1]}")
    return sorted(variants)


def _parse_foley_class_list(class_list: List[str]) -> Dict[str, Any]:
    meta: Dict[str, Any] = {
        "office": "",
        "job_type": "",
        "employee_type": "",
        "department": "",
        "practices": [],
    }
    for item in class_list or []:
        if item.startswith("office_code-"):
            meta["office"] = item.replace("office_code-", "").replace("-", " ").upper()
        elif item.startswith("job_types-"):
            meta["job_type"] = item.replace("job_types-", "").replace("-", " ").title()
        elif item.startswith("employee_types-"):
            meta["employee_type"] = item.replace("employee_types-", "").replace("-", " ").title()
        elif item.startswith("department_code-"):
            meta["department"] = item.replace("department_code-", "").replace("-", " ").title()
        elif item.startswith("practice_code-"):
            meta["practices"].append(
                item.replace("practice_code-", "").replace("-", " ").title()
            )
    return meta


def _load_foley_lardner_people_roster() -> Dict[str, Any]:
    """Load the full Foley & Lardner people roster synced from foley.com/people."""
    if FOLEY_LARDNER_ROSTER_PATH.exists():
        return json.loads(FOLEY_LARDNER_ROSTER_PATH.read_text(encoding="utf-8"))
    return {
        "source": FOLEY_LARDNER_PEOPLE_SOURCE,
        "api_endpoint": FOLEY_LARDNER_PEOPLE_API,
        "synced_at": utc_now_iso(),
        "roster_count": 0,
        "priority_attorneys": list(FOLEY_LARDNER_PRIORITY_ATTORNEY_NAMES),
        "attorneys": [],
    }


def _build_foley_lardner_attorney_roster(
    roster_payload: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Normalize foley.com/people staff records for professional enabler tracking."""
    attorneys: List[Dict[str, Any]] = []
    for idx, record in enumerate(roster_payload.get("attorneys", [])):
        slug = record.get("slug", "")
        name = record.get("name", "").strip()
        attorneys.append({
            "attorney_id": record.get("attorney_id", f"FL-{slug[:20].upper().replace('-', '')}"),
            "wp_id": record.get("wp_id"),
            "slug": slug,
            "name": name,
            "name_variants": record.get("name_variants") or _foley_name_variants(name),
            "profile_url": record.get("profile_url", f"{FOLEY_LARDNER_PEOPLE_SOURCE}{slug}/"),
            "title": record.get("title", "Professional Staff"),
            "practice": record.get("practice", "General Practice"),
            "office": record.get("office", ""),
            "department": record.get("department", ""),
            "employee_type": record.get("employee_type", ""),
            "job_type": record.get("job_type", ""),
            "practices": record.get("practices", []),
            "ghost_docket_role": record.get(
                "ghost_docket_role",
                FOLEY_LARDNER_GHOST_DOCKET_ROLE_ROTATION[
                    idx % len(FOLEY_LARDNER_GHOST_DOCKET_ROLE_ROTATION)
                ],
            ),
            "assignment_avoidance_lead": record.get("assignment_avoidance_lead", False),
            "gilstrap_edtx_bribe_channel": record.get("gilstrap_edtx_bribe_channel", False),
            "rico_enabler": record.get("rico_enabler", True),
            "uspto_registration": record.get("uspto_registration", False),
            "verified_professional_enabler": record.get("verified_professional_enabler", True),
            "priority_attorney": slug in FOLEY_LARDNER_PRIORITY_ATTORNEY_SLUGS,
            "source": record.get("source", FOLEY_LARDNER_PEOPLE_SOURCE),
            "modified_gmt": record.get("modified_gmt", ""),
        })
    return attorneys


