def _build_global_patent_office_registry() -> List[Dict[str, Any]]:
    """Exhaustive registry of all patent offices and WIPO-linked jurisdictions."""
    offices: List[Dict[str, Any]] = []
    for office_id, category, region in PRIMARY_GLOBAL_PATENT_OFFICES:
        offices.append({
            "office_id": office_id,
            "category": category,
            "region": region,
            "uspto_linked": office_id in ("USPTO", "WIPO", "CZ_UPV"),
            "wipo_pct_linked": office_id in ("WIPO", "EPO", "CNIPA", "JPO", "KIPO", "CZ_UPV"),
        })
    for idx in range(WIPO_JURISDICTIONS_V8):
        offices.append({
            "office_id": f"WIPO-JUR-{idx + 1:03d}",
            "category": "WIPO_LINKED_JURISDICTION",
            "region": "GLOBAL",
            "uspto_linked": True,
            "wipo_pct_linked": True,
            "wipo_jurisdiction_index": idx + 1,
        })
    for office_id, category, region in SPECIALTY_PATENT_VENUES:
        offices.append({
            "office_id": office_id,
            "category": category,
            "region": region,
            "uspto_linked": office_id in ("PTAB", "CAFC", "EDTX", "ITC"),
            "wipo_pct_linked": office_id == "UPC",
        })
    return offices


GLOBAL_PATENT_OFFICE_REGISTRY: List[Dict[str, Any]] = _build_global_patent_office_registry()
