def _load_victim_inventor_ohio_llc_roster() -> Dict[str, Any]:
    if VICTIM_INVENTOR_OHIO_LLC_ROSTER_PATH.exists():
        return json.loads(VICTIM_INVENTOR_OHIO_LLC_ROSTER_PATH.read_text(encoding="utf-8"))
    return {"entities": [], "ohio_llc_names": [], "roster_count": 0, "ohio_llc_count": 0}


def _build_victim_linked_corporations(roster: Dict[str, Any]) -> List[Dict[str, Any]]:
    corps: List[Dict[str, Any]] = []
    for record in roster.get("entities", []):
        corps.append({
            "name": record.get("name", ""),
            "aliases": record.get("name_variants", []),
            "jurisdiction": record.get("jurisdiction", "US"),
            "ohio_llc": record.get("ohio_llc", False),
            "entity_id": record.get("entity_id", ""),
            "entity_type": record.get("entity_type", "llc"),
            "chronology_index": record.get("chronology_index", 0),
            "chronology_phase": record.get("chronology_phase", ""),
            "legitimately_established": record.get("legitimately_established", True),
            "illicit_mirror": record.get("illicit_mirror", False),
            "domain": record.get("domain", ""),
            "blockchain_nexus": record.get("blockchain_nexus", True),
            "tokenized_ip_nexus": record.get("tokenized_ip_nexus", True),
        })
    return corps


