# -----------------------------------------------------------------------------
# Data Classes
# -----------------------------------------------------------------------------
@dataclass
class Patent:
    patent_id: str
    title: str
    abstract: str
    claims: List[str]
    description: str
    filing_date: str
    grant_date: str
    inventors: List[str]
    assignees: List[str]
    citations: List[str]
    jurisdiction: str
    family_id: str
    classification: List[str]
    blockchain_relations: List[Dict[str, Any]] = field(default_factory=list)
    raw_data: Dict[str, Any] = field(default_factory=dict)
    risk_score: float = 0.0
    is_essential: bool = False


@dataclass
class BlockchainTransaction:
    tx_hash: str
    block_number: int
    timestamp: datetime
    from_address: str
    to_address: str
    value: float
    gas_used: int
    gas_price: float
    status: str
    chain: str
    token_transfers: List[Dict[str, Any]] = field(default_factory=list)
    nft_transfers: List[Dict[str, Any]] = field(default_factory=list)
    related_patents: List[str] = field(default_factory=list)
    risk_score: float = 0.0
    raw_data: Dict[str, Any] = field(default_factory=dict)
    systemic_risk_factors: Dict[str, Any] = field(default_factory=dict)


@dataclass
class EntityAnalysis:
    entity_id: str
    entity_type: str
    patents_held: List[Patent]
    transactions: List[BlockchainTransaction]
    related_entities: List[str]
    risk_score: float
    compliance_status: str
    legal_actions: List[Dict[str, Any]]
    financial_health: float = 1.0
    jurisdiction: str = "Unknown"
    name: str = ""
    systemic_risk_factors: Dict[str, Any] = field(default_factory=dict)


@dataclass
class DeFiProtocol:
    name: str
    tvl: float
    current_utilization: float
    risk_score: float = 0.0
    systemic_risk_factors: Dict[str, Any] = field(default_factory=dict)


@dataclass
class Stablecoin:
    name: str
    symbol: str
    market_cap: float
    peg_currency: str
    reserve_assets: Dict[str, float]
    risk_score: float = 0.0
    systemic_risk_factors: Dict[str, Any] = field(default_factory=dict)


@dataclass
class Bridge:
    name: str
    tvl: float
    chains_connected: List[str]
    security_audits: List[Dict[str, Any]]
    risk_score: float = 0.0
    systemic_risk_factors: Dict[str, Any] = field(default_factory=dict)


@dataclass
class PatentFamily:
    """Deterministically traced stolen global patent family."""

    family_id: str
    family_index: int
    title: str
    abstract: str
    victim_inventor: str
    primary_jurisdiction: str
    member_jurisdictions: List[str]
    filing_date: str
    grant_date: str
    classification: List[str]
    assignee_shell: str
    stolen_status: str
    seed_provenance: List[str]
    trace_hash: str
    risk_score: float
    forward_citations: int
    linked_wipo_ids: List[str] = field(default_factory=list)
    blockchain_wallet: str = ""
    raw_data: Dict[str, Any] = field(default_factory=dict)


@dataclass
class WIPOFiling:
    """Deterministically traced WIPO PCT filing linked to a patent family."""

    wipo_id: str
    filing_index: int
    family_id: str
    family_index: int
    title: str
    abstract: str
    publication_date: str
    ipc_classes: List[str]
    inventors: List[str]
    assignees: List[str]
    stolen_status: str
    seed_provenance: List[str]
    trace_hash: str
    chain_of_custody: List[str] = field(default_factory=list)
    raw_data: Dict[str, Any] = field(default_factory=dict)


@dataclass
class OhioLLC:
    """Deterministically traced hijacked Ohio LLC from victim inventor portfolio."""

    llc_id: str
    llc_index: int
    name: str
    state: str
    victim_inventor: str
    linked_family_id: str
    stolen_royalty_usd: Decimal
    wallet_address: str
    trace_hash: str
    hijack_status: str = "confirmed_hijacked"
    seed_provenance: List[str] = field(default_factory=list)
    raw_data: Dict[str, Any] = field(default_factory=dict)


