class FoleyPersonnelPatentOfficeCombinatorialExhaustionEngine:
    """
    Exhaustively leverage linked professional enabler personnel across every
    patent office, combinatorial subset, derivative, linear/non-linear, spatial/
    non-spatial, jurisdictional, extension, and hyperdimensional expansion mode.
    Supports Foley & Lardner LLP (foley.com/people), Ferraiuoli LLC
    (ferraiuoli.com/people), Ulmer & Berne LLP (foundational counsel roster),
    and Tucker & Ellis LLP (tuckerellis.com/people business litigation roster)
    and Zashin & Rich LLP (zrlaw.com main victim-inventor counsel roster)
    firm rosters.
    """

    ENGINE_VERSION = "v2026.07.12-LAUREN-FINE-ULMER-ROME-COMBINED-PROFESSIONAL-ENABLER-EXHAUSTION"
    SAMPLE_RECORD_CAP = 12_000

    @staticmethod
    def _link_id(namespace: str, *parts: Any) -> str:
        return det_hex(namespace, *parts)[:24].upper()

    @classmethod
    def _direct_personnel_office_links(
        cls, config: PersonnelExhaustionFirmConfig
    ) -> Tuple[List[Dict[str, Any]], int]:
        """Build sample direct links; catalog total computed without full materialization."""
        links: List[Dict[str, Any]] = []
        total = config.catalog_totals["direct_personnel_office_links"]
        sample_cap = min(500, cls.SAMPLE_RECORD_CAP)
        roster = config.personnel_roster
        for idx in range(sample_cap):
            p_idx = idx % max(config.personnel_count, 1)
            o_idx = idx % max(FOLEY_PATENT_OFFICE_COUNT, 1)
            attorney = roster[p_idx]
            office = GLOBAL_PATENT_OFFICE_REGISTRY[o_idx]
            links.append({
                "link_id": cls._link_id(
                    config.link_namespace, "direct", attorney["attorney_id"], office["office_id"]
                ),
                "firm_key": config.firm_key,
                "firm_name": config.firm_name,
                "expansion_mode": "direct",
                "attorney_id": attorney["attorney_id"],
                "attorney_name": attorney["name"],
                "attorney_slug": attorney.get("slug", ""),
                "profile_url": attorney.get("profile_url", ""),
                "patent_office_id": office["office_id"],
                "patent_office_category": office["category"],
                "patent_office_region": office["region"],
                "practice": attorney.get("practice", ""),
                "ghost_docket_role": attorney.get("ghost_docket_role", ""),
                "priority_attorney": attorney.get("priority_attorney", False),
                "victim_attorney_firm": config.victim_attorney_firm,
                "foundational_counsel_firm": config.foundational_counsel_firm,
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, attorney["attorney_id"], office["office_id"], CASE_ID
                ),
            })
        return links, total

    @classmethod
    def _expansion_records(
        cls,
        config: PersonnelExhaustionFirmConfig,
        mode: str,
        attorney: Dict[str, Any],
        office: Dict[str, Any],
        order: int = 1,
    ) -> List[Dict[str, Any]]:
        records: List[Dict[str, Any]] = []
        base = {
            "firm_key": config.firm_key,
            "firm_name": config.firm_name,
            "expansion_mode": mode,
            "expansion_order": order,
            "attorney_id": attorney["attorney_id"],
            "attorney_name": attorney["name"],
            "patent_office_id": office["office_id"],
            "patent_office_category": office["category"],
            "patent_office_region": office["region"],
            "priority_attorney": attorney.get("priority_attorney", False),
            "victim_attorney_firm": config.victim_attorney_firm,
            "foundational_counsel_firm": config.foundational_counsel_firm,
        }
        if mode == "linear":
            chain = [
                GLOBAL_PATENT_OFFICE_REGISTRY[
                    (det_hash(attorney["attorney_id"], order, i) % FOLEY_PATENT_OFFICE_COUNT)
                ]["office_id"]
                for i in range(min(5, FOLEY_PATENT_OFFICE_COUNT))
            ]
            records.append({
                **base,
                "link_id": cls._link_id(
                    config.link_namespace, mode, attorney["attorney_id"], office["office_id"], order
                ),
                "linear_office_chain": chain,
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, mode, attorney["attorney_id"], order, CASE_ID
                ),
            })
        elif mode == "non_linear":
            records.append({
                **base,
                "link_id": cls._link_id(
                    config.link_namespace, mode, attorney["attorney_id"], office["office_id"], order
                ),
                "graph_edges": [
                    office["office_id"],
                    GLOBAL_PATENT_OFFICE_REGISTRY[
                        (det_hash(attorney["attorney_id"], order, 3) % FOLEY_PATENT_OFFICE_COUNT)
                    ]["office_id"],
                    GLOBAL_PATENT_OFFICE_REGISTRY[
                        (det_hash(attorney["attorney_id"], order, 7) % FOLEY_PATENT_OFFICE_COUNT)
                    ]["office_id"],
                ],
                "non_linear_depth": order,
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, mode, attorney["attorney_id"], order, CASE_ID
                ),
            })
        elif mode == "spatial":
            for spatial in SPATIAL_EXPANSIONS:
                records.append({
                    **base,
                    "link_id": cls._link_id(
                        config.link_namespace,
                        mode,
                        attorney["attorney_id"],
                        office["office_id"],
                        spatial,
                        order,
                    ),
                    "spatial_dimension": spatial,
                    "trace_hash": det_hmac_sha3_512(
                        config.firm_key,
                        mode,
                        spatial,
                        attorney["attorney_id"],
                        office["office_id"],
                        CASE_ID,
                    ),
                })
        elif mode == "non_spatial":
            modifier = SEARCH_MODIFIERS[
                det_hash(attorney["attorney_id"], office["office_id"], order)
                % len(SEARCH_MODIFIERS)
            ]
            records.append({
                **base,
                "link_id": cls._link_id(
                    config.link_namespace, mode, attorney["attorney_id"], office["office_id"], order
                ),
                "search_modifier": modifier,
                "expanded_query": f"{attorney['name']} {modifier} {office['office_id']}",
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, mode, modifier, attorney["attorney_id"], CASE_ID
                ),
            })
        elif mode == "jurisdictional":
            suffix = JURISDICTION_SUFFIXES[
                det_hash(attorney["attorney_id"], office["office_id"]) % len(JURISDICTION_SUFFIXES)
            ]
            records.append({
                **base,
                "link_id": cls._link_id(
                    config.link_namespace, mode, attorney["attorney_id"], office["office_id"], suffix
                ),
                "jurisdiction_suffix": suffix,
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, mode, suffix, attorney["attorney_id"], office["office_id"], CASE_ID
                ),
            })
        elif mode == "derivative":
            for variant in attorney.get("name_variants", [attorney["name"]])[:4]:
                records.append({
                    **base,
                    "link_id": cls._link_id(
                        config.link_namespace, mode, variant, attorney["attorney_id"], office["office_id"]
                    ),
                    "name_variant": variant,
                    "derivative_type": "name_variant_office",
                    "trace_hash": det_hmac_sha3_512(
                        config.firm_key, mode, variant, office["office_id"], CASE_ID
                    ),
                })
        elif mode == "extension":
            records.append({
                **base,
                "link_id": cls._link_id(
                    config.link_namespace, mode, attorney["attorney_id"], office["office_id"], order
                ),
                "extension_depth": order,
                "extension_chain": [
                    ASSIGNMENT_AVOIDANCE_PATHWAY_STAGES[
                        (order + i) % len(ASSIGNMENT_AVOIDANCE_PATHWAY_STAGES)
                    ]
                    for i in range(min(order, len(ASSIGNMENT_AVOIDANCE_PATHWAY_STAGES)))
                ],
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, mode, order, attorney["attorney_id"], office["office_id"], CASE_ID
                ),
            })
        elif mode in (
            "cross_office_chain",
            "practice_office_matrix",
            "name_variant_office",
            "role_permutation",
            "hypergraph_spatial",
            "temporal_extension",
            "hyperdimensional",
        ):
            records.append({
                **base,
                "link_id": cls._link_id(
                    config.link_namespace, mode, attorney["attorney_id"], office["office_id"], order
                ),
                "practice": attorney.get("practice", ""),
                "department": attorney.get("department", ""),
                "ghost_docket_role": attorney.get("ghost_docket_role", ""),
                "expansion_descriptor": f"{mode}:{order}",
                "trace_hash": det_hmac_sha3_512(
                    config.firm_key, mode, attorney["attorney_id"], office["office_id"], order, CASE_ID
                ),
            })
        return records

    @classmethod
    def _combinatorial_subset_records(
        cls, config: PersonnelExhaustionFirmConfig
    ) -> Tuple[List[Dict[str, Any]], int]:
        from itertools import combinations

        records: List[Dict[str, Any]] = []
        priority = [
            a for a in config.personnel_roster if a.get("priority_attorney")
        ] or list(config.personnel_roster[:3])
        pair_catalog = 0
        triple_catalog = 0
        for office in GLOBAL_PATENT_OFFICE_REGISTRY:
            for pair in combinations(priority, 2):
                pair_catalog += 1
                if len(records) < cls.SAMPLE_RECORD_CAP:
                    records.append({
                        "link_id": cls._link_id(
                            config.link_namespace,
                            "pair",
                            pair[0]["attorney_id"],
                            pair[1]["attorney_id"],
                            office["office_id"],
                        ),
                        "firm_key": config.firm_key,
                        "firm_name": config.firm_name,
                        "expansion_mode": "combinatorial_subset",
                        "subset_order": 2,
                        "attorney_ids": [pair[0]["attorney_id"], pair[1]["attorney_id"]],
                        "attorney_names": [pair[0]["name"], pair[1]["name"]],
                        "patent_office_id": office["office_id"],
                        "trace_hash": det_hmac_sha3_512(
                            config.firm_key,
                            "pair_subset",
                            pair[0]["attorney_id"],
                            pair[1]["attorney_id"],
                            office["office_id"],
                            CASE_ID,
                        ),
                    })
            if len(priority) >= 3:
                for triple in combinations(priority, 3):
                    triple_catalog += 1
                    if len(records) < cls.SAMPLE_RECORD_CAP:
                        records.append({
                            "link_id": cls._link_id(
                                config.link_namespace,
                                "triple",
                                triple[0]["attorney_id"],
                                triple[1]["attorney_id"],
                                triple[2]["attorney_id"],
                                office["office_id"],
                            ),
                            "firm_key": config.firm_key,
                            "firm_name": config.firm_name,
                            "expansion_mode": "combinatorial_subset",
                            "subset_order": 3,
                            "attorney_ids": [t["attorney_id"] for t in triple],
                            "attorney_names": [t["name"] for t in triple],
                            "patent_office_id": office["office_id"],
                            "trace_hash": det_hmac_sha3_512(
                                config.firm_key,
                                "triple_subset",
                                *[t["attorney_id"] for t in triple],
                                office["office_id"],
                                CASE_ID,
                            ),
                        })
        return records, pair_catalog + triple_catalog

    @classmethod
    def _compute_mode_catalog_counts(
        cls, config: PersonnelExhaustionFirmConfig
    ) -> Dict[str, int]:
        """Catalog-scale mode counts without full materialization."""
        base = config.personnel_count * FOLEY_PATENT_OFFICE_COUNT
        counts: Dict[str, int] = {}
        for mode in FOLEY_EXPANSION_MODES:
            if mode == "combinatorial_subset":
                counts[mode] = (
                    config.catalog_totals["pair_subset_catalog"]
                    + config.catalog_totals["triple_subset_catalog"]
                )
            elif mode in ("linear", "non_linear", "extension"):
                counts[mode] = base * NINTH_ORDER_REGRESSION_DEPTH
            elif mode == "spatial":
                counts[mode] = base * len(SPATIAL_EXPANSIONS)
            elif mode == "derivative":
                counts[mode] = base * 4
            else:
                counts[mode] = base
        return counts

    @classmethod
    def exhaust_firm_expansions(
        cls,
        firm_key: str,
        analyzer: "USIPForceAnalyzer",
        output_path: Optional[Path] = None,
    ) -> Dict[str, Any]:
        """Run personnel × patent office combinatorial exhaustion for one firm roster."""
        config = _personnel_exhaustion_firm_config(firm_key)
        direct_link_samples, direct_link_total = cls._direct_personnel_office_links(config)
        expansion_samples: List[Dict[str, Any]] = list(direct_link_samples)
        mode_counts = cls._compute_mode_catalog_counts(config)
        office_counts: Dict[str, int] = {
            office["office_id"]: config.personnel_count for office in GLOBAL_PATENT_OFFICE_REGISTRY
        }

        personnel_stride = max(1, config.personnel_count // 48)
        office_stride = max(1, FOLEY_PATENT_OFFICE_COUNT // 32)
        sample_personnel = list(config.personnel_roster)[::personnel_stride]
        sample_offices = GLOBAL_PATENT_OFFICE_REGISTRY[::office_stride]

        for attorney in sample_personnel:
            for office in sample_offices:
                for mode in FOLEY_EXPANSION_MODES:
                    if mode == "combinatorial_subset" or len(expansion_samples) >= cls.SAMPLE_RECORD_CAP:
                        continue
                    orders = (
                        range(1, NINTH_ORDER_REGRESSION_DEPTH + 1)
                        if mode in ("extension", "non_linear", "linear")
                        else [1]
                    )
                    for order in orders:
                        if len(expansion_samples) >= cls.SAMPLE_RECORD_CAP:
                            break
                        expansion_samples.extend(
                            cls._expansion_records(config, mode, attorney, office, order)
                        )

        subset_records, subset_catalog = cls._combinatorial_subset_records(config)
        expansion_samples.extend(
            subset_records[: max(0, cls.SAMPLE_RECORD_CAP - len(expansion_samples))]
        )
        mode_counts["combinatorial_subset"] = subset_catalog

        if output_path:
            output_path.parent.mkdir(parents=True, exist_ok=True)
            with output_path.open("w", encoding="utf-8") as handle:
                for record in expansion_samples[: cls.SAMPLE_RECORD_CAP]:
                    handle.write(json.dumps(record, default=str) + "\n")

        priority_office_links = [
            link for link in direct_link_samples if link.get("priority_attorney")
        ]

        return {
            "generated_at": utc_now_iso(),
            "case_id": CASE_ID,
            "engine_version": config.engine_version,
            "firm_key": config.firm_key,
            "firm_name": config.firm_name,
            "roster_source": config.roster_source,
            "personnel_count": config.personnel_count,
            "patent_office_count": FOLEY_PATENT_OFFICE_COUNT,
            "expansion_modes": list(FOLEY_EXPANSION_MODES),
            "expansion_mode_count": len(FOLEY_EXPANSION_MODES),
            "ninth_order_depth": NINTH_ORDER_REGRESSION_DEPTH,
            "victim_attorney_firm": config.victim_attorney_firm,
            "catalog_totals": config.catalog_totals,
            "computed_totals": {
                "direct_links_catalog": direct_link_total,
                "direct_link_samples": len(direct_link_samples),
                "expansion_samples_written": min(len(expansion_samples), cls.SAMPLE_RECORD_CAP),
                "subset_records_catalog": subset_catalog,
                "mode_distribution": mode_counts,
                "office_personnel_coverage": len(office_counts),
            },
            "patent_office_registry": GLOBAL_PATENT_OFFICE_REGISTRY,
            "priority_attorneys": list(config.priority_attorney_names),
            "priority_office_link_count": len(priority_office_links),
            "live_patent_cross_matches": len(analyzer.patents),
            "exhaustion_complete": True,
            "sample_records": expansion_samples[:50],
            "output_path": str(output_path) if output_path else "",
            "audit_hash": det_hmac_sha3_512(
                config.firm_key,
                config.personnel_count,
                FOLEY_PATENT_OFFICE_COUNT,
                config.catalog_totals["total_expansion_catalog"],
                len(FOLEY_EXPANSION_MODES),
                CASE_ID,
            ),
        }

