    @classmethod
    def extract_top_ten_immediately_actionable_insights(
        cls,
        analyzer: "USIPForceAnalyzer",
    ) -> Dict[str, Any]:
        """Rank and return top 10 immediately actionable prosecutorial insights."""
        candidates = cls._candidate_insights(analyzer)
        ranked = sorted(
            candidates,
            key=lambda c: (
                c["actionability_score"],
                1 if c["urgency"] == "immediate" else 0,
            ),
            reverse=True,
        )
        top_ten = ranked[:10]
        for idx, insight in enumerate(top_ten, start=1):
            insight["rank"] = idx
            insight["immediately_actionable"] = insight["urgency"] == "immediate"

        immediate_count = sum(1 for i in top_ten if i.get("immediately_actionable"))
        md_lines = [
            "# Top Ten Immediately Actionable Prosecutorial Insights",
            "",
            f"**Case ID:** {CASE_ID}",
            f"**Generated:** {utc_now_iso()}",
            f"**Victim Inventor:** {VICTIM_UBO}",
            f"**Investigation Scope:** {INVESTIGATION_TEMPORAL_SCOPE}",
            f"**Blockchain Scope:** {BLOCKCHAIN_TEMPORAL_SCOPE}",
            "",
        ]
        for insight in top_ten:
            md_lines.extend([
                f"## {insight['rank']}. {insight['title']}",
                "",
                f"- **Class:** {insight['insight_class']}",
                f"- **Urgency:** {insight['urgency']}",
                f"- **Actionability Score:** {insight['actionability_score']}",
                f"- **Statutes:** {', '.join(insight['statutes'])}",
                f"- **Detail:** {insight['detail']}",
                f"- **Remediation:** {insight['recommended_remediation']}",
                f"- **Evidence:** {', '.join(insight['evidence_references'])}",
                "",
            ])

        return {
            "generated_at": utc_now_iso(),
            "case_id": CASE_ID,
            "extractor_version": cls.EXTRACTOR_VERSION,
            "victim_inventor": VICTIM_UBO,
            "investigation_temporal_scope": INVESTIGATION_TEMPORAL_SCOPE,
            "blockchain_temporal_scope": BLOCKCHAIN_TEMPORAL_SCOPE,
            "total_candidates_evaluated": len(candidates),
            "top_ten_immediately_actionable": top_ten,
            "immediate_action_count": immediate_count,
            "all_candidates_ranked": ranked,
            "markdown_report": "\n".join(md_lines),
            "exhaustion_complete": len(top_ten) >= 10,
            "audit_hash": det_hmac_sha3_512(
                len(top_ten),
                immediate_count,
                CASE_ID,
                "prosecutorial_top_ten",
            ),
        }


