    @classmethod
    def _all_enabler_targets(cls) -> List[Dict[str, Any]]:
        """Flatten firm + individual attorney enabler targets for allocation."""
        targets: List[Dict[str, Any]] = []
        for enabler in GHOST_DOCKET_PROFESSIONAL_ENABLERS:
            targets.append({
                "target_id": enabler["entity"],
                "entity": enabler["entity"],
                "entity_type": enabler["entity_type"],
                "role": enabler["role"],
                "is_attorney": False,
                "firm": enabler["entity"],
            })
            for attorney in enabler.get("attorneys", []):
                targets.append({
                    "target_id": attorney["attorney_id"],
                    "entity": attorney["name"],
                    "entity_type": "attorney",
                    "role": attorney.get("ghost_docket_role", enabler["role"]),
                    "is_attorney": True,
                    "firm": enabler["entity"],
                    "attorney_record": attorney,
                })
        return targets

