async def run_omega_aegis_forensic_suite(
    session: ClientSession,
    analyzer: "USIPForceAnalyzer",
) -> Dict[str, Any]:
    """Execute US IPFORCE forensic suite and return JSON + written report."""
    inventor = VICTIM_UBO.split(",")[0].strip()
    monolith = OmegaAegisMonolith(session, inventor, analyzer)
    investigation = await monolith.run()
    written_report = OmegaAegisForensicReportGenerator.generate_written_report(
        investigation
    )
    return {
        "phase": "omega_aegis_forensic_suite",
        "version": OMEGA_AEGIS_SUITE_VERSION,
        "investigation": investigation,
        "written_report_md": written_report,
        "hash_chain_root": investigation.get("hash_chain_root", ""),
        "prosecutorial_referral_ready": investigation.get(
            "prosecutorial_referral_ready", True
        ),
        "standards_compliance": investigation.get("standards_compliance", {}),
    }


