def ultima_deterministic_hash(*args: Any) -> str:
    """FIPS 140-3 compliant deterministic HMAC-SHA3-512 for Ultima Genesis Final."""
    return det_hmac_sha3_512(*args)


@dataclass
class UltimaArchiveRecord:
    task_id: str
    data: Union[Dict[str, Any], List[Any], str]
    timestamp: str
    record_hash: str
    signature: str = ""

    @classmethod
    def from_payload(cls, task_id: str, data: Union[Dict, List, str]) -> "UltimaArchiveRecord":
        serialized = json.dumps(data, sort_keys=True, default=str)
        return cls(
            task_id=task_id,
            data=data,
            timestamp=utc_now_iso(),
            record_hash=ultima_deterministic_hash(serialized),
            signature=ultima_deterministic_hash(task_id, serialized, "signature"),
        )


