            patent_spoofed = anti_spoof.get("patent_corpus_audit", {}).get("spoofed_count", 0)
            roster_spoofed = anti_spoof.get("attorney_roster_audit", {}).get(
                "total_spoofed_attorneys", 0
            )
            quorum_failures = anti_spoof.get("embedded_consensus_audit", {}).get(
                "quorum_failure_count", 0
            )
            ratios.append(1.0 if integrity else 0.0)
            ratios.append(
                1.0 if patent_spoofed <= spec.get("max_spoofed_records", 0) else 0.0
            )
            ratios.append(1.0 if roster_spoofed == 0 else 0.0)
            ratios.append(1.0 if quorum_failures == 0 else 0.0)
            if not integrity:
                gaps.append("primary_source_anti_spoof_integrity_failed")
            if patent_spoofed > spec.get("max_spoofed_records", 0):
                gaps.append("spoofed_patent_records_detected")
            if roster_spoofed > 0:
                gaps.append("spoofed_attorney_roster_entries_detected")
            if quorum_failures > 0:
                gaps.append("embedded_consensus_quorum_failures")

